import{_ as a}from"./chunks/jerk_limited_trajectory_1d.CAKHw4-a.js";import{_ as r,o as _,c as i,al as o}from"./chunks/framework.7vp1BMOE.js";const M=JSON.parse('{"title":"多旋翼的加加速度限制型轨迹","description":"","frontmatter":{},"headers":[],"relativePath":"zh/config_mc/mc_jerk_limited_type_trajectory.md","filePath":"zh/config_mc/mc_jerk_limited_type_trajectory.md"}'),t={name:"zh/config_mc/mc_jerk_limited_type_trajectory.md"};function c(n,e,d,l,m,f){return _(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="多旋翼的加加速度限制型轨迹" tabindex="-1">多旋翼的加加速度限制型轨迹 <a class="header-anchor" href="#多旋翼的加加速度限制型轨迹" aria-label="Permalink to &quot;多旋翼的加加速度限制型轨迹&quot;">​</a></h1><p>The Jerk-limited trajectory type provides smooth motion in autonomous flight e.g. for filming, mapping, cargo. 它能产生对称的平滑 S-曲线使加加速度和加速度的极限始终得到保证。</p><p>This trajectory type is always enabled in autonomous modes like <a href="./../flight_modes_mc/mission">Mission mode</a>.</p><h2 id="轨迹生成器" tabindex="-1">轨迹生成器 <a class="header-anchor" href="#轨迹生成器" aria-label="Permalink to &quot;轨迹生成器&quot;">​</a></h2><p>下图显示了具有如下约束的典型加加速度限制剖面：</p><ul><li><code>jMax</code>: maximum jerk</li><li><code>a0</code>: initial acceleration</li><li><code>aMax</code>: maximum acceleration</li><li><code>a3</code>: final acceleration (always 0)</li><li><code>v0</code>: initial velocity</li><li><code>vRef</code>: desired velocity</li></ul><p>The constraints <code>jMax</code>, <code>aMax</code> are configurable by the user via parameters and can be different in manual position control and auto mode.</p><p>所得的速度剖面通常称为“S-曲线”。</p><p><img src="'+a+'" alt="Jerk-limited trajectory"></p><h2 id="手动模式" tabindex="-1">手动模式 <a class="header-anchor" href="#手动模式" aria-label="Permalink to &quot;手动模式&quot;">​</a></h2><p>In manual position and altitude mode, jerk limiting is applied only to the vertical axis. Full throttle stick deflection commands the maximum vertical velocity which is <a href="./../advanced_config/parameter_reference#MPC_Z_VEL_MAX_UP">MPC_Z_VEL_MAX_UP</a> upwards and <a href="./../advanced_config/parameter_reference#MPC_Z_VEL_MAX_DN">MPC_Z_VEL_MAX_DN</a> downwards.</p><h3 id="约束" tabindex="-1">约束 <a class="header-anchor" href="#约束" aria-label="Permalink to &quot;约束&quot;">​</a></h3><p>Z-axis</p><ul><li><code>jMax</code>: <a href="./../advanced_config/parameter_reference#MPC_JERK_MAX">MPC_JERK_MAX</a></li><li><code>aMax</code> (upward motion): <a href="./../advanced_config/parameter_reference#MPC_ACC_UP_MAX">MPC_ACC_UP_MAX</a></li><li><code>aMax</code> (downward motion): <a href="./../advanced_config/parameter_reference#MPC_ACC_DOWN_MAX">MPC_ACC_DOWN_MAX</a></li></ul><h2 id="自动模式" tabindex="-1">自动模式 <a class="header-anchor" href="#自动模式" aria-label="Permalink to &quot;自动模式&quot;">​</a></h2><p>In auto mode, the desired velocity is <a href="./../advanced_config/parameter_reference#MPC_XY_CRUISE">MPC_XY_CRUISE</a> but this value is automatically adjusted depending on the distance to the next waypoint, the maximum possible velocity in the waypoint and the maximum desired acceleration and jerk. The vertical speed is defined by <a href="./../advanced_config/parameter_reference#MPC_Z_V_AUTO_UP">MPC_Z_V_AUTO_UP</a> (upward motion) and <a href="./../advanced_config/parameter_reference#MPC_Z_V_AUTO_DN">MPC_Z_V_AUTO_DN</a> (downward motion).</p><h3 id="约束-1" tabindex="-1">约束 <a class="header-anchor" href="#约束-1" aria-label="Permalink to &quot;约束&quot;">​</a></h3><p>XY平面：</p><ul><li><code>jMax</code>: <a href="./../advanced_config/parameter_reference#MPC_JERK_AUTO">MPC_JERK_AUTO</a></li><li><code>aMax</code>: <a href="./../advanced_config/parameter_reference#MPC_ACC_HOR">MPC_ACC_HOR</a></li></ul><p>Z轴：</p><ul><li><code>jMax</code>: <a href="./../advanced_config/parameter_reference#MPC_JERK_AUTO">MPC_JERK_AUTO</a></li><li><code>aMax</code> (upward motion): <a href="./../advanced_config/parameter_reference#MPC_ACC_UP_MAX">MPC_ACC_UP_MAX</a></li><li><code>aMax</code> (downward motion): <a href="./../advanced_config/parameter_reference#MPC_ACC_DOWN_MAX">MPC_ACC_DOWN_MAX</a></li></ul><p>渐进某个航点时的距离-速度增益：</p><ul><li><a href="./../advanced_config/parameter_reference#MPC_XY_TRAJ_P">MPC_XY_TRAJ_P</a></li></ul><h3 id="相关参数" tabindex="-1">相关参数 <a class="header-anchor" href="#相关参数" aria-label="Permalink to &quot;相关参数&quot;">​</a></h3><ul><li><a href="./../advanced_config/parameter_reference#MPC_XY_VEL_MAX">MPC_XY_VEL_MAX</a></li><li><a href="./../advanced_config/parameter_reference#MPC_Z_VEL_MAX_UP">MPC_Z_VEL_MAX_UP</a></li><li><a href="./../advanced_config/parameter_reference#MPC_Z_VEL_MAX_DN">MPC_Z_VEL_MAX_DN</a></li><li><a href="./../advanced_config/parameter_reference#MPC_TKO_SPEED">MPC_TKO_SPEED</a></li><li><a href="./../advanced_config/parameter_reference#MPC_LAND_SPEED">MPC_LAND_SPEED</a></li><li><a href="./../advanced_config/parameter_reference#MPC_LAND_ALT1">MPC_LAND_ALT1</a></li><li><a href="./../advanced_config/parameter_reference#MPC_LAND_ALT2">MPC_LAND_ALT2</a></li></ul>',25)])])}const s=r(t,[["render",c]]);export{M as __pageData,s as default};
